<?php
$pageTitle='Refund receipt | Moleqra';require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/commerce.php';require_once __DIR__.'/includes/refunds.php';$pdo=db();$token=(string)($_GET['token']??'');$refundId=(int)($_GET['refund']??0);$order=$pdo&&commerce_schema_ready($pdo)?commerce_order_by_token($pdo,$token):null;$refund=null;if($order&&refunds_schema_ready($pdo)){$s=$pdo->prepare("SELECT * FROM order_refunds WHERE id=:id AND order_id=:order AND status='Processed'");$s->execute(['id'=>$refundId,'order'=>$order['id']]);$refund=$s->fetch()?:null;}if(!$order||!$refund)http_response_code(404);require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><div class="eyebrow">Refund receipt</div><h1><?= e($refund['refund_number']??'Refund unavailable') ?></h1></div></section><section class="section"><div class="container narrow"><?php if(!$refund):?><div class="card">This refund receipt is not available.</div><?php else:?><article class="card"><p><strong>Order:</strong> <?= e($order['order_number']) ?><br><strong>Processed:</strong> <?= e($refund['processed_at']) ?><br><strong>Amount:</strong> <?= e($refund['currency']) ?> <?= number_format((float)$refund['amount'],2) ?><br><strong>Reason:</strong> <?= e($refund['reason']) ?><?php if($refund['gateway_reference']):?><br><strong>Gateway reference:</strong> <?= e($refund['gateway_reference']) ?><?php endif;?></p><p>This receipt records the refund processed against the original Moleqra order.</p><button class="btn" type="button" onclick="window.print()">Print receipt</button></article><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
